import 'package:chopper/chopper.dart';

@ChopperApi()
abstract class MyService extends ChopperService {
  @Get(path: '/users')
  Future<Response> getUsers();
}

void main() async {
  final chopper = ChopperClient(services: [MyService.create()],);
  final service = chopper.getService<MyService>();
  final response = await service.getUsers();
  print(response.body);
}
